/** Writes docs/ipc-schema.json from packages/contracts/src/ipc.ts (desktop IPC commands and events). */
import { writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { COMMANDS, EVENTS } from '../packages/contracts/src/ipc.ts';

const doc = {
  $comment:
    'Generated by `pnpm run docs:ipc`. Desktop manager IPC (milestone 02). Rust re-validates every input.',
  commands: Object.fromEntries(
    Object.entries(COMMANDS).map(([name, c]) => [name, { args: c.args, result: c.result }]),
  ),
  events: EVENTS,
};
const out = join(import.meta.dirname, '..', 'docs', 'ipc-schema.json');
writeFileSync(out, `${JSON.stringify(doc, null, 2)}\n`);
console.log(`wrote ${out}: ${Object.keys(COMMANDS).length} commands, ${Object.keys(EVENTS).length} events`);
